#define PI 3.14159265358979
#define rot(a) mat2(cos(a), sin(a), -sin(a), cos(a))// 

void mainImage(out vec4 O, vec2 U){
        vec2 R = iResolution.xy,
             p = .3*U/R.y;//(U+U - R)/R.y;

        vec2 a,b,c,d,e,f,g,h,  u,v, w, uv, vw;

        float s=1., k = 1./(1.+sqrt(2.)), type ;

        // trangle (a,b,c) 
        b.y = 1.;
        a.x = 1.;

        //type=1.;a=1.414*vec2(0,sin(PI/8.)),b=1.414*vec2(cos(PI/8.),0);

        vec2 newa, newb, newc;

        for(int i =0;i<5;i++)        {
                if(type<.5){
                        d = c+(b-c)*k;
                        e = c+(a-c)*k;
                        f = a+(b-a)*k;
                        g = (f+b)*.5;
                        if(dot(p-d, b+f-d-d)<0.){// 最下面

                                //newa =d;
                                //newb =e;////////////:://
                                //newc =c;
                                a=d, b=e;
                        }else if(dot(p-d, e-d)<0.){
                                //newc = g;
                                //newa = b;
                                //newb = d;
                                c=g, a=b, b=d;
                        }else if(dot(p-d, c-b)<0.){
                                //newc = g;
                                //newa = d;
                                //newb = f;
                                c=g, a=d, b=f;
                        }else{
                                type=1.;
                                h = (f+e)*.5;
                                //float y = dot(p-h, f-e), x = dot(p-h, a-d);
                                vec2 v = (p-h)*mat2(a-d,f-e);//float x=v.x,y=v.y;
                                if(v.x>=0. && v.y>=0.){
                                        //newa = f;
                                        //newb =a;
                                        //newc =h;
                                        b=a,a=f,c=h;

                                }else if(v.x<0. && v.y>=0.){
                                        //newa = f;
                                        //newb = d;
                                        //newc = h;
                                        a=f,b=d,c=h;
                                }else if(v.x<0. && v.y<0.){
                                        //newa = e;
                                        //newb = d;
                                        //newc = h;
                                        a=e,b=d,c=h;
                                }else{
                                        //newa = e;
                                        //newb = a;
                                        //newc = h;    
                                        b=a, a=e, c=h;
                                }
                        }
                }else{
                        d = c-(b-c)+(b+b-c-c)*(1.-k);
                        e = a+(b-a)*(1.-k);/////
                        f = (a+e)*.5;
                        if(dot(p-d, e-d)<0.){
                                //newa = d;
                                //newb = a;
                                //newc = c;
                                b=a,a=d;
                        }else if(dot(p-e,d-b)<0.){
                                //newa = e;
                                //newb = b;
                                //newc = (b+d)*.5;
                                a=e, c = (b+d)*.5;
                        }else if(dot(p-d, a-d)<0.){
                                //newa = e;
                                //newb = d;
                                //newc = (b+d)*.5;
                                a=e,c = (b+d)*.5, b=d;
                        }else{
                                type = 0.;
                                if(dot(p-f, a-b)>0.){
                                        //newa = a;
                                        //newb =d;
                                        //newc=f;
                                        b=d, c=f;
                                }else{
                                        //newa =d;
                                        //newb = e;
                                        //newc=f;
                                        a=d,b=e,c=f;
                                }
                        }
                }
                //a=newa;
                //b=newb;
                //c=newc;
        }
        g = p-a;
        f= normalize(b-a);
        float dist= abs(f.x*g.y-f.y*g.x);

        if(iMouse.x<iResolution.x*.33 && type>.5){
             g = p-c;
             f= normalize(b-c);
             dist= min(dist, abs(f.x*g.y-f.y*g.x));
        }else if(iMouse.x>iResolution.x*.66){
             g = p-a;
             f= normalize(a-c);
             dist= min(dist, abs(f.x*g.y-f.y*g.x));
        }

        dist /= length(a-b);
        O = vec4( smoothstep( .1, 0., dist) );
}
